SELECT id, department_id, doctor_id, patient_id, date_time, purpose, status, bill_amount
FROM appointments
WHERE id = #{id}

SELECT id, department_id, doctor_id, patient_id, date_time, purpose, status, bill_amount
FROM appointments
WHERE doctor_id = #{doctorId}

SELECT id, department_id, doctor_id, patient_id, date_time, purpose, status, bill_amount
FROM appointments
WHERE patient_id = #{patientId}
